$ErrorActionPreference='Stop';. (Join-Path $PSScriptRoot '..\meeting_pack.ps1');$source=Join-Path $PSScriptRoot '..\data\projects.example.json';$revision=Get-MeetingPackRevision $source;$body=@{format='xlsx';mode='preview';scope='Entire portfolio';projectIds=@();revision=$revision}|ConvertTo-Json;$result=Invoke-MeetingPackExport $body $source $source (Split-Path (Split-Path $source)) $false;$path=Join-Path $env:TEMP ('sami-meeting-pack-'+[guid]::NewGuid().ToString('n')+'.xlsx');[IO.File]::WriteAllBytes($path,$result.Bytes)
$excel=$null;$book=$null
try{$excel=New-Object -ComObject Excel.Application;$excel.Visible=$false;$excel.DisplayAlerts=$false;$book=$excel.Workbooks.Open($path,0,$true);if($book.Worksheets.Count-ne1){throw'Workbook must contain exactly one sheet.'};$sheet=$book.Worksheets.Item(1);if($sheet.Name-ne'Projects'){throw'Only sheet must be Projects.'};if([string]::IsNullOrWhiteSpace([string]$sheet.Range('A4').Text)){throw'First project row is empty.'};if($sheet.Shapes.Count-lt1){throw'SAMI icon is missing.'};'MEETING_PACK_EXCEL_OPEN_OK'}finally{if($book){$book.Close($false)};if($excel){$excel.Quit()};if(Test-Path $path){Remove-Item $path -Force};[GC]::Collect();[GC]::WaitForPendingFinalizers()}
